// scripts/build-styles.ts — the ONE decisions-style build face (W2267.8):
// compiles hooks/board-html/decisions.scss (the same-name source) through
// design-ui's compileStylesheet into the generated CSS module the board
// page interpolates. Sass computes structure at build time; the theme
// rides the kernel layer's --klh-* custom properties at runtime, so the
// generated sheet is theme-free (semantic tokens only). package.json's
// build:styles runs this file verbatim; editing the generated file is
// always wrong — edit the .scss.
import { writeFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { compileStylesheet } from "@klh/design-ui/build/scss-plugin.ts";

const ROOT = resolve(import.meta.dir, "..");
const SCSS = join(ROOT, "hooks/board-html/decisions.scss");
const OUT = join(ROOT, "hooks/board-html/decisions-css.ts");

/** Compile decisions.scss → the DECISIONS_CSS string module. */
export function buildDecisionsStyles(): string {
	const css = compileStylesheet(SCSS);
	const mod = [
		"// GENERATED by scripts/build-styles.ts — edit decisions.scss, never this file.\n",
		"export const DECISIONS_CSS = ",
		JSON.stringify(css),
		";\n",
	].join("");
	writeFileSync(OUT, mod);
	return css;
}

if (import.meta.main) {
	const css = buildDecisionsStyles();
	console.log(`decisions styles → ${OUT} (${css.length} bytes css)`);
}
